{"command": "create", "file_text": "package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"
)

type App struct {
	cfg   *Config
	store *Store
	mux   *http.ServeMux
}

func main() {
	cfg := loadConfig()

	if cfg.ResetOnly {
		if err := runReset(cfg); err != nil {
			fmt.Fprintln(os.Stderr, "reset:", err)
			os.Exit(1)
		}
		return
	}
	if cfg.ResetAndSeed {
		if err := runReset(cfg); err != nil {
			fmt.Fprintln(os.Stderr, "reset:", err)
			os.Exit(1)
		}
	}

	if err := runServer(cfg); err != nil {
		fmt.Fprintln(os.Stderr, "server:", err)
		os.Exit(1)
	}
}

func runReset(cfg *Config) error {
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	store, err := openStore(ctx, cfg)
	if err != nil {
		return err
	}
	defer store.Close()

	schema, err := schemaSQL()
	if err != nil {
		return err
	}
	if _, err := store.PG.Exec(ctx, schema); err != nil {
		return fmt.Errorf("apply schema: %w", err)
	}
	if err := store.resetMongo(ctx); err != nil {
		return fmt.Errorf("reset mongo: %w", err)
	}
	if err := store.seedDefaults(ctx); err != nil {
		return fmt.Errorf("seed defaults: %w", err)
	}
	if err := store.ensureInitialServiceability(ctx); err != nil {
		return fmt.Errorf("serviceability: %w", err)
	}
	fmt.Println("reset complete")
	return nil
}

func runServer(cfg *Config) error {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	store, err := openStore(ctx, cfg)
	if err != nil {
		return err
	}
	defer store.Close()

	// Ensure schema exists (idempotent) so the app can start even before reset.
	schema, err := schemaSQL()
	if err == nil {
		_, _ = store.PG.Exec(ctx, schema)
	}
	_ = store.seedDefaults(ctx)
	_ = store.ensureInitialServiceability(ctx)

	// Bootstrap admin if no users exist.
	if err := store.bootstrapAdmin(ctx, cfg); err != nil {
		fmt.Fprintln(os.Stderr, "bootstrap admin:", err)
	}

	app := &App{cfg: cfg, store: store, mux: http.NewServeMux()}
	app.registerRoutes()

	srv := &http.Server{
		Addr:    cfg.HTTPAddr,
		Handler: loggingMW(corsMW(app.mux)),
	}

	go app.periodicTasks(ctx)

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	errCh := make(chan error, 1)
	go func() {
		fmt.Println("listening on", cfg.HTTPAddr)
		errCh <- srv.ListenAndServe()
	}()

	select {
	case <-stop:
		ctx2, c2 := context.WithTimeout(context.Background(), 10*time.Second)
		defer c2()
		_ = srv.Shutdown(ctx2)
	case err := <-errCh:
		return err
	}
	return nil
}

func (a *App) periodicTasks(ctx context.Context) {
	t := time.NewTicker(15 * time.Second)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			a.store.expireOffers(ctx)
			a.store.flagDeadlineExceptions(ctx)
		}
	}
}

// registerRoutes wires all 45 endpoints plus the readiness check and static frontend.
func (a *App) registerRoutes() {
	mux := a.mux

	// Readiness (public)
	mux.HandleFunc("/ready", a.handleReadiness)

	// Auth (public)
	mux.HandleFunc("/api/authenticate-user", a.handleAuthenticate)

	// Public GET endpoints that require auth
	mux.Handle("/api/read-sample-state/", a.authMW(http.HandlerFunc(a.handleReadSampleState)))
	mux.Handle("/api/read-user/", a.authMW(http.HandlerFunc(a.handleReadUser)))
	mux.Handle("/api/ui/bootstrap", a.authMW(http.HandlerFunc(a.handleUIBootstrap)))
	mux.Handle("/api/events", a.authMW(http.HandlerFunc(a.handleStreamEvents)))

	// Authenticated POST endpoints. Each handler enforces its own role checks.
	post := func(path string, h http.HandlerFunc) {
		mux.Handle(path, a.authMW(h))
	}
	post("/api/select-active-role", a.handleSelectActiveRole)
	post("/api/check-serviceability", a.handleCheckServiceability)
	post("/api/create-collection-request", a.handleCreateCollectionRequest)
	post("/api/ingest-presealed-sample", a.handleIngestPresealed)
	post("/api/list-role-work", a.handleListRoleWork)
	post("/api/read-journey-plan", a.handleReadJourneyPlan)
	post("/api/read-sample-lifecycle", a.handleReadSampleLifecycle)
	post("/api/read-operations-state", a.handleReadOperationsState)
	post("/api/read-serviceability-snapshot", a.handleReadServiceabilitySnapshot)
	post("/api/search-audit-trail", a.handleSearchAuditTrail)

	post("/api/accept-assignment", a.handleAcceptAssignment)
	post("/api/decline-assignment", a.handleDeclineAssignment)
	post("/api/collect-and-seal-sample", a.handleCollectAndSeal)
	post("/api/record-worker-location", a.handleRecordWorkerLocation)
	post("/api/update-assignment-progress", a.handleUpdateAssignmentProgress)
	post("/api/initiate-handoff", a.handleInitiateHandoff)
	post("/api/confirm-handoff", a.handleConfirmHandoff)
	post("/api/record-handling-checkpoint", a.handleRecordHandlingCheckpoint)
	post("/api/confirm-laboratory-receipt", a.handleConfirmLabReceipt)
	post("/api/record-laboratory-exception", a.handleRecordLabException)
	post("/api/set-worker-availability", a.handleSetWorkerAvailability)

	post("/api/configure-capacity", a.handleConfigureCapacity)
	post("/api/configure-laboratory-acceptance", a.handleConfigureLabAcceptance)
	post("/api/create-location", a.handleCreateLocation)
	post("/api/update-location", a.handleUpdateLocation)
	post("/api/create-connection", a.handleCreateConnection)
	post("/api/set-connection-status", a.handleSetConnectionStatus)
	post("/api/set-location-status", a.handleSetLocationStatus)
	post("/api/set-location-function-status", a.handleSetLocationFunctionStatus)
	post("/api/create-sample-type", a.handleCreateSampleType)
	post("/api/update-sample-type", a.handleUpdateSampleType)
	post("/api/create-user", a.handleCreateUser)
	post("/api/update-user-access", a.handleUpdateUserAccess)

	post("/api/cancel-journey", a.handleCancelJourney)
	post("/api/reroute-journey", a.handleRerouteJourney)
	post("/api/split-journey", a.handleSplitJourney)
	post("/api/merge-journeys", a.handleMergeJourneys)
	post("/api/edit-active-plan", a.handleEditActivePlan)
	post("/api/report-disruption", a.handleReportDisruption)

	// Static frontend + map assets
	a.registerStatic()
}

// registerStatic serves the SPA and map assets, falling back to index.html.
func (a *App) registerStatic() {
	fd := a.cfg.FrontendDir
	if _, err := os.Stat(fd); err != nil {
		fd = "/workspace/backend/frontend_dist"
	}
	abs, _ := filepath.Abs(fd)
	fs := http.FileServer(http.Dir(abs))
	a.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		// map assets served under /assets/maps if present
		if strings.HasPrefix(r.URL.Path, "/assets/") {
			fs.ServeHTTP(w, r)
			return
		}
		// SPA fallback
		up := r.URL.Path
		if up == "/" {
			serveIndex(w, abs)
			return
		}
		full := filepath.Join(abs, filepath.Clean(up))
		if info, err := os.Stat(full); err == nil && !info.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		serveIndex(w, abs)
	})
}

func serveIndex(w http.ResponseWriter, dir string) {
	b, err := os.ReadFile(filepath.Join(dir, "index.html"))
	if err != nil {
		http.NotFound(w, nil)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Write(b)
}

// --- middleware ---

func loggingMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		ww := &statusRecorder{ResponseWriter: w, status: 200}
		next.ServeHTTP(ww, r)
		fmt.Printf("%s %s %d %s\n", r.Method, r.URL.Path, ww.status, time.Since(start))
	})
}

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (s *statusRecorder) WriteHeader(code int) {
	s.status = code
	s.ResponseWriter.WriteHeader(code)
}

func corsMW(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, X-Idempotency-Key")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		if r.Method == http.MethodOptions {
			w.WriteHeader(http.StatusNoContent)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// --- readiness ---

func (a *App) handleReadiness(w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()
	if err := a.store.PG.Ping(ctx); err != nil {
		writeJSON(w, 503, map[string]string{"status": "not_ready", "error": "postgres"})
		return
	}
	if err := a.store.Mongo.Ping(ctx, nil); err != nil {
		writeJSON(w, 503, map[string]string{"status": "not_ready", "error": "mongo"})
		return
	}
	writeJSON(w, 200, map[string]string{"status": "ready"})
}

// --- session management ---

func (a *App) resolveSession(ctx context.Context, token string) (*AuthUser, error) {
	if token == "" {
		return nil, errors.New("no token")
	}
	var u AuthUser
	var roles, quals []string
	var assignedLoc *string
	err := a.store.PG.QueryRow(ctx, `
		SELECT u.id, u.username, u.roles, u.qualifications, s.active_role, u.assigned_location_id
		FROM sessions s JOIN users u ON u.id = s.user_id
		WHERE s.token = $1 AND s.expires_at > now() AND u.active = true`, token).
		Scan(&u.ID, &u.Username, &roles, &quals, &u.ActiveRole, &assignedLoc)
	if err != nil {
		return nil, err
	}
	u.Roles = roles
	u.Qualifications = quals
	if assignedLoc != nil {
		u.AssignedLoc = *assignedLoc
	}
	return &u, nil
}

func newToken() string {
	b := make([]byte, 24)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// helper to parse optional int query/field
func atoiOr(s string, def int) int {
	v, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil {
		return def
	}
	return v
}

