		toJSON(body.Roles), toJSONStr(body.Qualifications), toJSONStr(body.Certifications), body.Active, nullableUUID(body.AssignedLoc)).Scan(&id)
	if err != nil {
		writeError(w, apiErr(409, "concurrent_conflict", err.Error()))
		return
	}
	a.store.audit(ctx, AuditEntry{UserID: currentUser(r).ID, Role: currentRole(r), Action: "create_user",
		ItemType: "user", ItemID: id, Outcome: "success"})
	u, _ := a.store.getUser(ctx, id)
	writeData(w, 201, u)
