// sampleDetail builds the full sample view for a requester/owner.
func (s *Store) sampleDetail(ctx context.Context, sampleID string) (map[string]interface{}, error) {
	var (
		id, status, originType                                           string
		sealed                                                           bool
		holderID, journeyID, labID                                       *string
		originLat, originLon, latestLat, latestLon                       *float64
		locRecordedAt                                                    *time.Time
		serviceability, serviceabilityReason                             string
		exceptionRaw                                                     []byte
		requesterID, sampleTypeID                                        string
	)
	err := s.PG.QueryRow(ctx, `SELECT id, requester_id, sample_type_id, status, sealed, current_holder_id, active_journey_id, target_laboratory_id,
		origin_type, origin_lat, origin_lon, latest_lat, latest_lon, location_recorded_at, serviceability, serviceability_reason, exception
		FROM samples WHERE id=$1`, sampleID).
		Scan(&id, &requesterID, &sampleTypeID, &status, &sealed, &holderID, &journeyID, &labID,
			&originType, &originLat, &originLon, &latestLat, &latestLon, &locRecordedAt, &serviceability, &serviceabilityReason, &exceptionRaw)
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{
		"sampleId":             id,
		"requesterId":          requesterID,
		"sampleTypeId":         sampleTypeID,
		"status":               status,
		"sealed":               sealed,
		"originType":           originType,
		"serviceability":       serviceability,
		"serviceabilityReason": serviceabilityReason,
	}
	if holderID != nil {
		out["currentHolderId"] = *holderID
	}
	if journeyID != nil {
		out["activeJourneyId"] = *journeyID
	}
	if labID != nil {
		out["targetLaboratoryId"] = *labID
	}
	if originLat != nil {
		out["originLat"] = *originLat
		out["originLon"] = *originLon
	}
	if latestLat != nil {
		out["latestLat"] = *latestLat
		out["latestLon"] = *latestLon
		out["currentLocation"] = map[string]interface{}{"latitude": *latestLat, "longitude": *latestLon}
	}
	stale := false
	if locRecordedAt != nil {
		out["locationRecordedAt"] = locRecordedAt.UTC().Format(time.RFC3339)
		if time.Since(*locRecordedAt) > 30*time.Minute {
			stale = true
		}
	}
	out["stale"] = stale
	if len(exceptionRaw) > 0 {
		var ex interface{}
		_ = json.Unmarshal(exceptionRaw, &ex)
		out["exception"] = ex
		out["exceptionFlag"] = true
	} else {
		out["exceptionFlag"] = false
	}
	// Add the status timeline (ordered) from Mongo.
	tl, _ := s.sampleTimeline(ctx, sampleID)
	out["statusHistory"] = tl
	return out, nil
}

// sampleTimeline returns the ordered list of status-change events for a sample.
func (s *Store) sampleTimeline(ctx context.Context, sampleID string) ([]map[string]interface{}, error) {
	cur, err := s.Mongo.Database("arena").Collection("sample_events").Find(ctx, bson.M{"sampleId": sampleID})
	if err != nil {
		return nil, err
	}
	defer cur.Close(ctx)
	var results []map[string]interface{}
	for cur.Next(ctx) {
		var doc map[string]interface{}
		if err := cur.Decode(&doc); err == nil {
			results = append(results, doc)
		}
	}
	if results == nil {
		results = []map[string]interface{}{}
	}
	return results, nil
}

