func (s *Store) journeyPlan(ctx context.Context, journeyID string) (map[string]interface{}, error) {
	var id string
	var version int
	var routeMode, status string
	var estDelivery *time.Time
	var valid bool
	err := s.PG.QueryRow(ctx, `SELECT id, plan_version, route_mode, status, estimated_delivery_at, valid FROM journeys WHERE id=$1`, journeyID).
		Scan(&id, &version, &routeMode, &status, &estDelivery, &valid)
	if err != nil {
		return nil, err
	}
	out := map[string]interface{}{
		"journeyId": id, "planVersion": version, "routeMode": routeMode, "status": status, "valid": valid,
	}
	if estDelivery != nil {
		out["estimatedDeliveryAt"] = estDelivery.UTC().Format(time.RFC3339)
	}
	asns := []interface{}{}
	rows, _ := s.PG.Query(ctx, `SELECT id, kind, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM assignments WHERE journey_id=$1 ORDER BY sequence`, journeyID)
	defer rows.Close()
	for rows.Next() {
		var aid, kind, st, sid string
		var seq int
		var fromID, toID, wid *string
		_ = rows.Scan(&aid, &kind, &seq, &st, &fromID, &toID, &wid, &sid)
		entry := map[string]interface{}{"assignmentId": aid, "kind": kind, "sequence": seq, "status": st, "sampleId": sid}
		if fromID != nil {
			entry["fromLocationId"] = *fromID
		}
		if toID != nil {
			entry["toLocationId"] = *toID
		}
		if wid != nil {
			entry["workerId"] = *wid
		}
		asns = append(asns, entry)
	}
	out["assignments"] = asns
	return out, nil
}

